export const page = "<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n  <title>Backloggd Atlas — Your games, in perspective</title>\n  <meta name=\"description\" content=\"Explore your Backloggd game ratings by release year, developer, and more.\">\n  <link rel=\"icon\" type=\"image/svg+xml\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' rx='14' fill='%2314171b'/%3E%3Cpath d='M13 44V27h8v17zm15 0V16h8v28zm15 0V32h8v12z' fill='%23d7ff62'/%3E%3C/svg%3E\">\n  <style>\n    :root{font-family:Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,sans-serif;color:#edf0ed;background:#111417;font-size:16px}*{box-sizing:border-box}body{margin:0}button,input{font:inherit}button{cursor:pointer}a{color:inherit} .shell{max-width:1440px;margin:auto;padding:0 36px 64px}.top{height:88px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #30353a;gap:20px}.brand{display:flex;align-items:center;gap:12px;font-size:1.15rem;font-weight:800;letter-spacing:-.04em;white-space:nowrap}.mark{width:32px;height:32px;background:#d7ff62;border-radius:8px;color:#14171b;display:grid;place-items:center;font-size:20px;font-weight:900}.topright{display:flex;align-items:center;gap:12px}.source{color:#9ba49f;font-size:.88rem}.upload{border:1px solid #d7ff62;background:#d7ff62;color:#14171b;border-radius:8px;padding:11px 16px;font-weight:750}.upload:hover{background:#edffb1}.upload:focus-visible,.ghost:focus-visible,.seg button:focus-visible{outline:3px solid white;outline-offset:3px}#file{position:absolute;opacity:0;width:1px;height:1px}.heading{display:flex;align-items:end;justify-content:space-between;gap:22px;padding:38px 0 28px}.eyebrow{color:#d7ff62;text-transform:uppercase;letter-spacing:.18em;font-size:.75rem;font-weight:750;margin:0 0 12px}h1{font-size:clamp(2.1rem,4vw,3.65rem);line-height:1.04;letter-spacing:-.065em;margin:0;font-weight:800}.intro{color:#a8b1aa;max-width:450px;line-height:1.5;margin:0}.mode{display:inline-flex;align-items:center;gap:8px;color:#b6c0b8;font-size:.85rem}.dot{width:8px;height:8px;border-radius:100%;background:#d7ff62}.notice{display:none;background:#263016;border:1px solid #657a31;color:#edffb6;padding:12px 16px;border-radius:9px;margin-bottom:18px}.notice.show{display:block}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:16px}.card{background:#1b2023;border:1px solid #30373b;border-radius:13px;padding:22px;min-width:0}.stat-label,.kicker{color:#a7b0a9;font-size:.78rem;text-transform:uppercase;letter-spacing:.12em;font-weight:700}.stat-value{font-size:clamp(2rem,3.2vw,3.2rem);letter-spacing:-.065em;font-weight:780;margin:11px 0 4px;line-height:1}.stat-sub{color:#b5bdb7;font-size:.85rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.grid{display:grid;grid-template-columns:1.45fr 1fr;gap:16px}.panel{background:#1b2023;border:1px solid #30373b;border-radius:13px;padding:25px;min-width:0}.panel h2{margin:0;font-size:1.25rem;letter-spacing:-.035em}.panel-head{display:flex;justify-content:space-between;align-items:start;gap:16px;margin-bottom:23px}.panel-sub{color:#aab4ad;font-size:.85rem;margin:6px 0 0}.seg{display:flex;background:#111619;border:1px solid #343c3e;padding:3px;border-radius:8px}.seg button{border:0;background:none;color:#adb7b0;padding:7px 11px;font-size:.76rem;border-radius:5px}.seg button.active{background:#d7ff62;color:#14171b;font-weight:700}.span2{grid-column:span 2}.chart{height:255px;position:relative}.bars{height:100%;display:flex;align-items:end;gap:5px;border-bottom:1px solid #4a5451;padding:0 3px 22px}.barcol{height:100%;flex:1;display:flex;flex-direction:column;justify-content:end;align-items:center;position:relative;min-width:0}.bar{width:min(100%,24px);min-height:2px;border-radius:4px 4px 0 0;background:#d7ff62;opacity:.86;transition:height .4s}.barcol:hover .bar{opacity:1;background:#f0ffbe}.barcol span{position:absolute;top:calc(100% - 17px);color:#96a19a;font-size:.68rem;white-space:nowrap}.barcol[data-tip]:hover:before{content:attr(data-tip);position:absolute;bottom:calc(var(--h) + 27px);background:#f0f3ea;color:#15191b;padding:6px 8px;border-radius:5px;font-size:.7rem;white-space:nowrap;z-index:2}.developer-list{display:flex;flex-direction:column;gap:17px}.dev-row{display:grid;grid-template-columns:minmax(100px,1fr) 46px;gap:12px;align-items:center}.dev-name{font-size:.9rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.dev-detail{color:#99a69e;font-size:.75rem;margin-top:3px}.score{font-size:1.2rem;font-weight:750;text-align:right;color:#d7ff62}.track{height:5px;background:#343d3a;border-radius:5px;margin-top:8px;overflow:hidden}.fill{height:100%;background:#d7ff62;border-radius:5px}.rating-layout{display:grid;grid-template-columns:185px 1fr;align-items:center;gap:24px}.donut{width:185px;height:185px;border-radius:50%;display:grid;place-items:center;position:relative}.donut:after{content:\"\";position:absolute;inset:28px;background:#1b2023;border-radius:50%}.donut-center{z-index:1;text-align:center;font-size:1.9rem;font-weight:750;letter-spacing:-.05em}.donut-center small{display:block;color:#9ca9a0;font-size:.7rem;font-weight:500;letter-spacing:0}.legend{display:flex;flex-direction:column;gap:11px}.legend-line{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:.84rem}.legend-label{display:flex;align-items:center;gap:8px}.swatch{width:10px;height:10px;border-radius:2px;flex:none}.legend-count{color:#aab4ac}.year-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:9px}.year-tile{border:1px solid #3c4740;background:#242d2a;border-radius:9px;padding:14px;min-width:0}.year-tile.best{background:#d7ff62;border-color:#d7ff62;color:#14171b}.year-num{font-size:1.55rem;font-weight:780;letter-spacing:-.05em}.year-score{margin-top:8px;font-size:1rem;font-weight:700}.year-games{font-size:.75rem;color:#adb9af;margin-top:3px}.year-tile.best .year-games{color:#3b4932}.foot{margin-top:21px;color:#8e9b92;font-size:.8rem;line-height:1.5}.ghost{border:1px solid #47504b;background:none;color:#e4eae2;padding:10px 13px;border-radius:8px;font-size:.82rem}.empty{color:#acb7af;padding:40px 0;text-align:center}.filehint{color:#8f9b93;font-size:.75rem;margin-top:8px}.sample-pill{color:#d7ff62;border:1px solid #53643c;padding:5px 8px;border-radius:30px;font-size:.72rem;font-weight:700;white-space:nowrap}@media(max-width:1000px){.grid{grid-template-columns:1fr}.span2{grid-column:auto}.stats{grid-template-columns:repeat(2,1fr)}.year-grid{grid-template-columns:repeat(5,1fr)}}@media(max-width:650px){.shell{padding:0 16px 40px}.top{height:72px}.brand{font-size:1rem}.source{display:none}.heading{display:block;padding:29px 0 22px}.intro{margin-top:14px}.stats{gap:9px}.card{padding:17px}.stat-value{font-size:2rem}.panel{padding:18px}.panel-head{flex-wrap:wrap}.rating-layout{grid-template-columns:1fr}.donut{margin:auto}.year-grid{grid-template-columns:repeat(2,1fr)}.year-tile:last-child{grid-column:span 2}.chart{height:215px}.barcol span{font-size:.58rem}}\n  .lookup{display:flex;align-items:center;gap:10px;background:#1b2023;border:1px solid #45514b;padding:9px;border-radius:12px;margin:0 0 16px;max-width:760px}.lookup input{flex:1;min-width:0;border:0;outline:0;background:transparent;color:#fff;padding:10px 12px;font-size:1rem}.lookup input::placeholder{color:#8e9b92}.lookup button{border:0;border-radius:8px;background:#d7ff62;color:#14171b;padding:11px 17px;font-weight:750;white-space:nowrap}.lookup button:disabled{opacity:.55;cursor:wait}.lookup:focus-within{border-color:#d7ff62}.lookup-help{color:#9daaa1;font-size:.85rem;margin:-5px 0 20px}.lookup-help strong{color:#e2ebe3;font-weight:600}.loading{display:none;align-items:center;gap:10px;color:#d7ff62;margin:0 0 16px;font-size:.9rem}.loading.show{display:flex}.spinner{width:15px;height:15px;border:2px solid #64715b;border-top-color:#d7ff62;border-radius:50%;animation:spin .8s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:650px){.lookup{padding:7px}.lookup button{padding:11px}.lookup input{font-size:.9rem}}\n  .drill{font:inherit;cursor:pointer;text-align:left}.dev-row.drill{width:100%;padding:10px;margin:-10px;border:1px solid transparent;border-radius:9px;background:transparent;color:inherit}.dev-row.drill:hover,.dev-row.drill[aria-expanded=\"true\"]{background:#29322b;border-color:#5b7049}.year-tile.drill{width:100%;color:#edf0ed}.year-tile.drill.best{color:#14171b}.year-tile.drill:hover,.year-tile.drill[aria-expanded=\"true\"]{outline:2px solid #ecffad;outline-offset:2px}.drill:focus-visible,.close:focus-visible{outline:3px solid #edf0ed;outline-offset:3px}.coverage{color:#b8c8a7}.breakdown-head{display:flex;align-items:start;justify-content:space-between;gap:16px;margin-bottom:16px}.breakdown-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.game-item{display:flex;align-items:center;justify-content:space-between;gap:16px;background:#252c2d;border:1px solid #394344;border-radius:9px;padding:13px 15px;min-width:0}.game-title{font-weight:650;min-width:0}.game-title a{color:#f1f6ed;text-decoration:none}.game-title a:hover{text-decoration:underline}.game-meta{color:#aebcb0;font-size:.78rem;margin-top:3px}.game-rating{color:#d7ff62;font-weight:800;white-space:nowrap}.close{background:transparent;border:1px solid #59645b;color:#edf0ed;border-radius:8px;padding:7px 10px}.panel[hidden]{display:none}@media(max-width:650px){.breakdown-list{grid-template-columns:1fr}.game-item{padding:12px}}\n  </style>\n</head>\n<body><div class=\"shell\">\n  <header class=\"top\"><div class=\"brand\"><div class=\"mark\" aria-hidden=\"true\">▥</div> Backloggd Atlas</div><div class=\"topright\"><span class=\"source\" id=\"sourceLabel\">Sample library</span><label class=\"upload\" for=\"file\">Import your library</label><input id=\"file\" type=\"file\" accept=\".csv,.json,text/csv,application/json\" aria-label=\"Import a Backloggd CSV or JSON export\"></div></header>\n  <main><div class=\"heading\"><div><p class=\"eyebrow\">Your gaming history, mapped</p><h1 id=\"title\">A closer look at your games.</h1></div><p class=\"intro\">Enter a Backloggd nickname or profile URL to map your public games, ratings, release years, and studios.</p></div>\n  <form class=\"lookup\" id=\"lookup\"><input id=\"username\" type=\"text\" autocomplete=\"off\" spellcheck=\"false\" placeholder=\"Nickname or backloggd.com/u/yourname\" aria-label=\"Backloggd nickname or profile URL\" required><button id=\"lookupButton\" type=\"submit\">Build dashboard</button></form>\n  <p class=\"lookup-help\"><strong>No sign-in needed.</strong> Public profiles only. Loading a large library may take a minute.</p><div id=\"loading\" class=\"loading\" role=\"status\"><span class=\"spinner\" aria-hidden=\"true\"></span><span id=\"progress\">Loading profile…</span></div>\n  <div id=\"notice\" class=\"notice\" role=\"status\"></div>\n  <section class=\"stats\" aria-label=\"Library overview\"><div class=\"card\"><div class=\"stat-label\">Library games</div><div class=\"stat-value\" id=\"played\">—</div><div class=\"stat-sub\" id=\"playedSub\">In this library</div></div><div class=\"card\"><div class=\"stat-label\">Average rating</div><div class=\"stat-value\" id=\"average\">—</div><div class=\"stat-sub\">Out of 5 stars</div></div><div class=\"card\"><div class=\"stat-label\">Top release year</div><div class=\"stat-value\" id=\"topYear\">—</div><div class=\"stat-sub\" id=\"topYearSub\">Highest average rating</div></div><div class=\"card\"><div class=\"stat-label\">Top listed studio</div><div class=\"stat-value\" id=\"topDev\" style=\"font-size:clamp(1.35rem,2vw,2rem);line-height:1.15\">—</div><div class=\"stat-sub\" id=\"topDevSub\">Highest rated company</div></div></section>\n  <div class=\"grid\"><section class=\"panel\"><div class=\"panel-head\"><div><h2>Games by release year</h2><p class=\"panel-sub\">The eras you keep coming back to</p></div><div class=\"seg\" role=\"group\" aria-label=\"Release year chart measure\"><button class=\"active\" id=\"countBtn\" type=\"button\">Games</button><button id=\"avgBtn\" type=\"button\">Avg. rating</button></div></div><div class=\"chart\"><div id=\"yearBars\" class=\"bars\" role=\"img\" aria-label=\"Games by release year\"></div></div></section>\n  <section class=\"panel\"><div class=\"panel-head\"><div><h2>Studios you rate highest</h2><p class=\"panel-sub\" id=\"devSubtitle\">First company listed · at least 2 rated games</p></div></div><div id=\"developers\" class=\"developer-list\"></div></section>\n  <section class=\"panel\"><div class=\"panel-head\"><div><h2>Your rating spread</h2><p class=\"panel-sub\">How often each score shows up</p></div></div><div class=\"rating-layout\"><div id=\"donut\" class=\"donut\"><div class=\"donut-center\" id=\"donutCenter\">—<small>rated games</small></div></div><div id=\"legend\" class=\"legend\"></div></div></section>\n  <section class=\"panel\"><div class=\"panel-head\"><div><h2>Best release years</h2><p class=\"panel-sub\" id=\"yearSubtitle\">Highest average scores · at least 2 rated games</p></div></div><div id=\"yearTiles\" class=\"year-grid\"></div></section>\n  <section class=\"panel span2\" id=\"breakdown\" aria-labelledby=\"breakdownTitle\" hidden><div class=\"breakdown-head\"><div><h2 id=\"breakdownTitle\">Games counted</h2><p class=\"panel-sub\" id=\"breakdownSubtitle\"></p></div><button class=\"close\" id=\"closeBreakdown\" type=\"button\" aria-label=\"Close game list\">Close</button></div><div id=\"breakdownList\" class=\"breakdown-list\"></div></section></div>\n  <div class=\"foot\"><span id=\"dataNote\">Showing a sample library. Profile lookups read public Backloggd pages; file imports stay in this browser.</span> <button class=\"ghost\" id=\"reset\" type=\"button\" style=\"display:none;margin-left:12px\">Show sample data</button><div class=\"filehint\">Backloggd lists companies without separating developer and publisher roles here, so studio rankings use the first listed company. CSV and JSON import remains available.</div></div>\n  </main></div>\n  <script>\n  const sample=[\n    ['Hades',2020,'Supergiant Games',5],['Hades II',2025,'Supergiant Games',4.5],['Transistor',2014,'Supergiant Games',4.5],['Bastion',2011,'Supergiant Games',4],['Pyre',2017,'Supergiant Games',4],\n    ['Celeste',2018,'Extremely OK Games',5],['TowerFall Ascension',2014,'Extremely OK Games',4.5],['Hollow Knight',2017,'Team Cherry',5],['Silksong',2025,'Team Cherry',4.5],\n    ['Portal 2',2011,'Valve',5],['Half-Life 2',2004,'Valve',4.5],['Portal',2007,'Valve',4.5],['Disco Elysium',2019,'ZA/UM',5],['The Witcher 3',2015,'CD Projekt RED',4.5],['Cyberpunk 2077',2020,'CD Projekt RED',4],\n    ['Outer Wilds',2019,'Mobius Digital',5],['Return of the Obra Dinn',2018,'Lucas Pope',5],['Papers, Please',2013,'Lucas Pope',4.5],['Stardew Valley',2016,'ConcernedApe',4.5],['Elden Ring',2022,'FromSoftware',5],['Sekiro',2019,'FromSoftware',4.5],['Dark Souls III',2016,'FromSoftware',4],\n    ['Baldur’s Gate 3',2023,'Larian Studios',5],['Divinity: Original Sin 2',2017,'Larian Studios',4.5],['Slay the Spire',2019,'Mega Crit',4.5],['Inscryption',2021,'Daniel Mullins Games',4],['Undertale',2015,'Toby Fox',5],['Deltarune',2018,'Toby Fox',4.5],\n    ['Control',2019,'Remedy Entertainment',4],['Alan Wake 2',2023,'Remedy Entertainment',5],['Death Stranding',2019,'Kojima Productions',4],['Journey',2012,'thatgamecompany',4.5],['The Last of Us',2013,'Naughty Dog',4.5],['The Last of Us Part II',2020,'Naughty Dog',4],\n    ['Minecraft',2011,'Mojang Studios',4.5],['Terraria',2011,'Re-Logic',4],['Tunic',2022,'Isometricorp Games',4.5],['Animal Well',2024,'Shared Memory',4.5],['Balatro',2024,'LocalThunk',5],['Dredge',2023,'Black Salt Games',4]\n  ].map(([title,year,developer,rating])=>({title,year,developer,rating,played:true}));\n  let games=sample,mode='count';const $=id=>document.getElementById(id);const esc=s=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));const avg=a=>a.reduce((s,n)=>s+n,0)/a.length;const fmt=n=>Number.isFinite(n)?n.toFixed(1):'—';\n  function isPlayed(g){return g.played!==false}function rated(){return games.filter(g=>isPlayed(g)&&Number.isFinite(g.rating)&&g.rating>0)}\n  function groups(items,key){const m=new Map;items.forEach(g=>{const k=g[key];if(k!==null&&k!==undefined&&k!==''&&k!=='Unknown'){if(!m.has(k))m.set(k,[]);m.get(k).push(g)}});return [...m].map(([name,list])=>({name,list,count:list.length,rating:avg(list.map(g=>g.rating))}))}\n  function render(){const played=games.filter(isPlayed),rs=rated(),yrs=groups(rs,'year').filter(x=>Number.isFinite(+x.name)),devs=groups(rs,'developer');const bestYears=yrs.filter(x=>x.count>=2).sort((a,b)=>b.rating-a.rating||b.count-a.count);const bestDevs=devs.filter(x=>x.count>=2).sort((a,b)=>b.rating-a.rating||b.count-a.count);const yearCoverage=played.filter(g=>g.year!=null&&Number.isFinite(+g.year)).length,studioCoverage=played.filter(g=>g.developer&&g.developer!=='Unknown').length;$('breakdown').hidden=true;$('devSubtitle').textContent=`First company listed · ${studioCoverage}/${played.length} games have studio data · select a studio to see its games`;$('yearSubtitle').textContent=`${yearCoverage}/${played.length} games have release-year data · select a year to see its games`;$('played').textContent=played.length;$('playedSub').textContent=`${rs.length} rated games`;$('average').textContent=rs.length?fmt(avg(rs.map(g=>g.rating))):'—';$('topYear').textContent=bestYears[0]?.name??'—';$('topYearSub').textContent=bestYears[0]?`${fmt(bestYears[0].rating)} / 5 across ${bestYears[0].count} rated games`:'Needs 2 rated games';$('topDev').textContent=bestDevs[0]?.name??'—';$('topDevSub').textContent=bestDevs[0]?`${fmt(bestDevs[0].rating)} / 5 across ${bestDevs[0].count} rated games`:'Needs 2 rated games';\n    const chartYears=groups((mode==='count'?played:rs).filter(g=>Number.isFinite(+g.year)),'year').sort((a,b)=>+a.name-+b.name).slice(-22);const max=Math.max(1,...chartYears.map(x=>mode==='count'?x.count:x.rating));$('yearBars').innerHTML=chartYears.length?chartYears.map(x=>{const v=mode==='count'?x.count:x.rating;const h=Math.max(2,v/max*94);return `<div class=\"barcol\" style=\"--h:${h}%\" data-tip=\"${esc(x.name)}: ${mode==='count'?x.count+' games':fmt(v)+' / 5'}\"><div class=\"bar\" style=\"height:${h}%\"></div><span>${String(x.name).slice(-2)}</span></div>`}).join(''):'<div class=\"empty\">No release years in this file</div>';$('yearBars').setAttribute('aria-label',mode==='count'?'Number of played games by release year':'Average rating by release year');\n    $('developers').innerHTML=bestDevs.length?bestDevs.slice(0,5).map(x=>`<button type=\"button\" class=\"dev-row drill\" data-kind=\"studio\" data-key=\"${esc(x.name)}\" aria-controls=\"breakdown\" aria-expanded=\"false\" aria-label=\"Show ${x.count} rated games counted for ${esc(x.name)}\"><div><div class=\"dev-name\" title=\"${esc(x.name)}\">${esc(x.name)}</div><div class=\"dev-detail\">${x.count} rated games · view games</div><div class=\"track\"><div class=\"fill\" style=\"width:${x.rating/5*100}%\"></div></div></div><div class=\"score\">${fmt(x.rating)}</div></button>`).join(''):'<div class=\"empty\">Studio data needs at least 2 rated games per company.</div>';\n    const buckets=[{label:'4.5–5',min:4.5,max:5,color:'#d7ff62'},{label:'3.5–4',min:3.5,max:4.49,color:'#9bc875'},{label:'2.5–3',min:2.5,max:3.49,color:'#648f8e'},{label:'1.5–2',min:1.5,max:2.49,color:'#6970a1'},{label:'0.5–1',min:0,max:1.49,color:'#4a5362'}].map(b=>({...b,count:rs.filter(g=>g.rating>=b.min&&g.rating<=b.max).length}));let pos=0;const slices=buckets.map(b=>{const start=pos;pos+=rs.length?b.count/rs.length*100:0;return `${b.color} ${start}% ${pos}%`}).join(',');$('donut').style.background=rs.length?`conic-gradient(${slices})`:'#353d3b';$('donutCenter').innerHTML=`${rs.length}<small>rated games</small>`;$('legend').innerHTML=buckets.map(b=>`<div class=\"legend-line\"><span class=\"legend-label\"><i class=\"swatch\" style=\"background:${b.color}\"></i>${b.label} stars</span><span class=\"legend-count\">${b.count}</span></div>`).join('');$('yearTiles').innerHTML=bestYears.length?bestYears.slice(0,5).map((x,i)=>`<button type=\"button\" class=\"year-tile drill ${i===0?'best':''}\" data-kind=\"year\" data-key=\"${esc(x.name)}\" aria-controls=\"breakdown\" aria-expanded=\"false\" aria-label=\"Show ${x.count} rated games counted for ${esc(x.name)}\"><div class=\"year-num\">${esc(x.name)}</div><div class=\"year-score\">★ ${fmt(x.rating)}</div><div class=\"year-games\">${x.count} rated games · view</div></button>`).join(''):'<div class=\"empty\">Release-year insights need at least 2 rated games per year.</div>'}\n  function parseCSV(s){const rows=[];let row=[],field='',quoted=false;for(let i=0;i<s.length;i++){const c=s[i];if(quoted){if(c==='\"'&&s[i+1]==='\"'){field+='\"';i++}else if(c==='\"')quoted=false;else field+=c}else if(c==='\"')quoted=true;else if(c===','){row.push(field);field=''}else if(c==='\\n'){row.push(field);rows.push(row);row=[];field=''}else if(c!=='\\r')field+=c}row.push(field);if(row.some(x=>x))rows.push(row);const header=(rows.shift()||[]).map(x=>x.trim());return rows.map(r=>Object.fromEntries(header.map((h,i)=>[h,r[i]??''])))}\n  function key(o,names){const entries=Object.entries(o);for(const n of names){const found=entries.find(([k])=>k.toLowerCase().replace(/[^a-z0-9]/g,'')===n);if(found)return found[1]}return ''}\n  function normalize(o){const title=key(o,['title','gametitle','gamename','name','game']);const rawRating=key(o,['rating','userrating','yourrating','score','userscore']);let rating=parseFloat(String(rawRating).replace(/[^0-9.]/g,''));if(rating>5&&rating<=10)rating/=2;if(!(rating>=0&&rating<=5))rating=NaN;const yearRaw=key(o,['releaseyear','year','released','releasedate','firstreleasedate']);const yearMatch=String(yearRaw).match(/(?:19|20)\\d{2}/);const year=yearMatch?+yearMatch[0]:null;let developer=key(o,['developer','developers','studio','studios','company']);if(Array.isArray(developer))developer=developer.map(x=>typeof x==='string'?x:x.name).filter(Boolean).join(', ');if(typeof developer==='object'&&developer)developer=developer.name||'';const status=String(key(o,['status','completionstatus','shelf','tab','state'])).toLowerCase();const played=!(status&&/backlog|wishlist|want to play|playing/.test(status));return {title:String(title||'').trim(),rating,year,developer:String(developer||'').trim()||'Unknown',played}}\n  function usernameFromInput(value){const input=value.trim();let username=input;if(/^https?:\\/\\//i.test(input)||input.toLowerCase().startsWith('backloggd.com/')){let url;try{url=new URL(/^https?:\\/\\//i.test(input)?input:'https://'+input)}catch{throw Error('Enter a valid Backloggd profile URL.')}if(!['backloggd.com','www.backloggd.com'].includes(url.hostname.toLowerCase()))throw Error('Use a backloggd.com profile URL.');username=url.pathname.match(/^\\/u\\/([^/]+)/i)?.[1]||''}if(!/^[A-Za-z0-9_-]{1,40}$/.test(username))throw Error('Enter a valid Backloggd nickname or profile URL.');return username}\n  async function api(path){const response=await fetch(path);const data=await response.json().catch(()=>({error:'The site returned an unreadable response.'}));if(!response.ok)throw Error(data.error||'Could not load Backloggd data.');return data}\n  async function loadProfile(username){\n    const all=[],seen=new Set;let lastSignature='',libraryIncomplete=false,metadataIncomplete=false;\n    for(let page=1;page<=100;page++){\n      let result;\n      try{result=await api(`/api/page?user=${encodeURIComponent(username)}&page=${page}`)}\n      catch(error){if(!all.length)throw error;libraryIncomplete=true;break}\n      const batch=result.games||[],signature=batch.map(g=>g.id).join(',');\n      if(!batch.length||signature===lastSignature)break;\n      lastSignature=signature;\n      const fresh=batch.filter(g=>!seen.has(g.id));\n      if(!fresh.length)break;\n      fresh.forEach(g=>{seen.add(g.id);all.push(g)});\n      $('progress').textContent=`Found ${all.length} games · loading page ${page}…`;\n      if(batch.length<36)break;\n      if(page===100)libraryIncomplete=true;\n    }\n    let failedBatches=0;\n    for(let i=0;i<all.length;i+=8){\n      const group=all.slice(i,i+8);\n      try{\n        const params=new URLSearchParams;group.forEach(g=>params.append('path',g.path));\n        const result=await api(`/api/details?${params}`);\n        const byPath=new Map(result.details.map(x=>[x.path,x]));\n        group.forEach(g=>Object.assign(g,byPath.get(g.path)||{}));\n        if(result.failed){metadataIncomplete=true;failedBatches++}else failedBatches=0;\n      }catch{metadataIncomplete=true;failedBatches++}\n      $('progress').textContent=`Found ${all.length} games · checked ${Math.min(i+8,all.length)} for release years and studios…`;\n      if(failedBatches>=3){metadataIncomplete=true;break}\n    }\n    return {all,libraryIncomplete,metadataIncomplete};\n  }\n  $('lookup').addEventListener('submit',async e=>{e.preventDefault();const notice=$('notice');notice.classList.remove('show');let username;try{username=usernameFromInput($('username').value)}catch(err){notice.textContent=err.message;notice.classList.add('show');return}const button=$('lookupButton');button.disabled=true;button.textContent='Loading…';$('loading').classList.add('show');$('progress').textContent='Loading profile…';try{const {all,libraryIncomplete,metadataIncomplete}=await loadProfile(username);if(!all.length)throw Error('No public games found for this profile.');games=all;$('sourceLabel').textContent='@'+username;$('title').textContent=`${username}'s games, at a glance.`;$('dataNote').textContent=`Showing ${all.length} public games from backloggd.com/u/${username}/. Refresh the dashboard to check for changes.`;$('reset').style.display='inline-block';render();const years=all.filter(g=>g.year).length,studios=all.filter(g=>g.developer!=='Unknown').length;notice.textContent=libraryIncomplete?`Showing ${all.length} games retrieved so far; Backloggd stopped responding before the library finished. Year data: ${years}/${all.length}; studio data: ${studios}/${all.length}.`:metadataIncomplete?`Loaded ${all.length} games. Backloggd limited game details, so year insights cover ${years}/${all.length} games and studio insights cover ${studios}/${all.length}.`:`Loaded ${all.length} games from @${username}.`;notice.classList.add('show')}catch(err){notice.textContent=err.message;notice.classList.add('show')}finally{button.disabled=false;button.textContent='Build dashboard';$('loading').classList.remove('show')}});\n  $('file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{const text=await file.text();const raw=file.name.toLowerCase().endsWith('.json')?JSON.parse(text):parseCSV(text);let records=Array.isArray(raw)?raw:(raw.games||raw.library||raw.entries||raw.data);if(!Array.isArray(records))throw Error('The file needs a list of games.');const next=records.map(normalize).filter(g=>g.title);if(!next.length)throw Error('No game titles were found. Check the column names in your export.');games=next;$('sourceLabel').textContent=file.name;$('title').textContent='Your library, at a glance.';$('dataNote').textContent=`Showing ${file.name}. Your imported file stays in this browser.`;$('reset').style.display='inline-block';const missing=[];if(!next.some(g=>Number.isFinite(g.rating)&&g.rating>0))missing.push('ratings');if(!next.some(g=>g.year))missing.push('release years');if(!next.some(g=>g.developer!=='Unknown'))missing.push('developers');const notice=$('notice');notice.textContent=missing.length?`Imported ${next.length} games. This file has no ${missing.join(', ')}, so some insights are unavailable.`:`Imported ${next.length} games from ${file.name}.`;notice.classList.add('show');render()}catch(err){$('notice').textContent=`Could not import this file: ${err.message}`;$('notice').classList.add('show')}e.target.value=''});\n  $('countBtn').onclick=()=>{mode='count';$('countBtn').classList.add('active');$('avgBtn').classList.remove('active');render()};$('avgBtn').onclick=()=>{mode='average';$('avgBtn').classList.add('active');$('countBtn').classList.remove('active');render()};$('reset').onclick=()=>{games=sample;$('sourceLabel').textContent='Sample library';$('title').textContent='A closer look at your games.';$('dataNote').textContent='Showing a sample library. Profile lookups read public Backloggd pages; file imports stay in this browser.';$('reset').style.display='none';$('notice').classList.remove('show');render()};\n  if(document.modelContext?.registerTool){Promise.resolve(document.modelContext.registerTool({name:'load_backloggd_profile',title:'Load Backloggd profile',description:'Build the visible dashboard from a public Backloggd nickname or profile URL.',inputSchema:{type:'object',properties:{profile:{type:'string'}},required:['profile'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},async execute(input){const username=usernameFromInput(input?.profile||'');$('username').value=username;const {all,libraryIncomplete,metadataIncomplete}=await loadProfile(username);if(!all.length)throw Error('No public games found.');games=all;$('sourceLabel').textContent='@'+username;$('title').textContent=`${username}'s games, at a glance.`;$('dataNote').textContent=`Showing ${all.length} public games from backloggd.com/u/${username}/.`;$('reset').style.display='inline-block';render();return{username,games:all.length,libraryIncomplete,metadataIncomplete}}})).catch(()=>{})}render();\n  let breakdownTrigger=null;\n  function showBreakdown(kind,key,trigger){\n    const list=rated().filter(g=>String(kind==='studio'?g.developer:g.year)===key).sort((a,b)=>b.rating-a.rating||a.title.localeCompare(b.title));\n    if(!list.length)return;\n    breakdownTrigger=trigger;\n    document.querySelectorAll('.drill[aria-expanded]').forEach(button=>button.setAttribute('aria-expanded',button===trigger?'true':'false'));\n    $('breakdownTitle').textContent=`Games counted for ${key}`;\n    $('breakdownSubtitle').textContent=`${list.length} rated games · ${fmt(avg(list.map(g=>g.rating)))} / 5 average · ${kind==='studio'?'first company listed on Backloggd':'release year shown on Backloggd'}`;\n    $('breakdownList').innerHTML=list.map(g=>{\n      const safePath=typeof g.path==='string'&&/^\\/games\\/[a-z0-9-]+\\/$/.test(g.path);\n      const title=safePath?`<a href=\"https://backloggd.com${esc(g.path)}\" target=\"_blank\" rel=\"noopener noreferrer\">${esc(g.title)} ↗</a>`:esc(g.title);\n      const detail=kind==='studio'?(g.year||'Year unknown'):(g.developer||'Studio unknown');\n      return `<div class=\"game-item\"><div class=\"game-title\">${title}<div class=\"game-meta\">${esc(detail)}</div></div><div class=\"game-rating\">★ ${fmt(g.rating)}</div></div>`;\n    }).join('');\n    $('breakdown').hidden=false;\n    $('breakdownTitle').setAttribute('tabindex','-1');\n    $('breakdownTitle').focus({preventScroll:true});\n    $('breakdown').scrollIntoView({behavior:'smooth',block:'nearest'});\n  }\n  for(const id of ['developers','yearTiles'])$(id).addEventListener('click',event=>{const button=event.target.closest('button[data-kind]');if(button)showBreakdown(button.dataset.kind,button.dataset.key,button)});\n  $('closeBreakdown').addEventListener('click',()=>{$('breakdown').hidden=true;document.querySelectorAll('.drill[aria-expanded]').forEach(button=>button.setAttribute('aria-expanded','false'));if(breakdownTrigger?.isConnected)breakdownTrigger.focus()});\n  </script>\n</body></html>\n";
